"""Extract Fable 5 conversational turns from Claude Code jsonl logs."""
import json, glob, os, re

PROJ = os.path.expanduser("~/.claude/projects")
OUT = "/home/lane/cc/data/fable5_raw.jsonl"

def text_of(content):
    """Join text blocks; return (text, thinking)."""
    if isinstance(content, str):
        return content.strip(), ""
    txt, think = [], []
    for b in content:
        if not isinstance(b, dict):
            continue
        if b.get("type") == "text":
            txt.append(b.get("text", ""))
        elif b.get("type") == "thinking":
            think.append(b.get("thinking", ""))
    return "\n".join(txt).strip(), "\n".join(think).strip()

def clean_user(content):
    """Return user text, or None if this is a tool_result / system noise."""
    if isinstance(content, str):
        s = content.strip()
        if not s or s.startswith("<") or "command-name" in s:
            return None
        return s
    parts = []
    for b in content:
        if isinstance(b, dict) and b.get("type") == "text":
            parts.append(b.get("text", ""))
        elif isinstance(b, dict) and b.get("type") == "tool_result":
            return None  # skip tool results as user turns
    s = "\n".join(parts).strip()
    return s or None

rows = []
for fn in glob.glob(f"{PROJ}/*/*.jsonl"):
    msgs = []
    for line in open(fn, errors="ignore"):
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get("type") not in ("user", "assistant"):
            continue
        m = o.get("message", {})
        msgs.append((o.get("type"), m.get("model"), m.get("content")))
    # pair: most recent real user text -> following fable-5 assistant text
    pending_user = None
    for typ, model, content in msgs:
        if typ == "user":
            u = clean_user(content)
            if u:
                pending_user = u
        elif typ == "assistant" and model == "claude-fable-5":
            txt, think = text_of(content)
            if txt and pending_user and len(txt) > 15:
                rows.append({
                    "source": os.path.basename(fn),
                    "user": pending_user,
                    "thinking": think,
                    "assistant": txt,
                })
                pending_user = None  # consume

os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w") as f:
    for r in rows:
        f.write(json.dumps(r) + "\n")

n_think = sum(1 for r in rows if r["thinking"])
print(f"extracted {len(rows)} pairs ({n_think} already have thinking) -> {OUT}")
print(f"avg user len {sum(len(r['user']) for r in rows)//max(len(rows),1)}, "
      f"avg asst len {sum(len(r['assistant']) for r in rows)//max(len(rows),1)}")

