#!/usr/bin/env python3
"""Extract FULL Fable-5 agent sequences: every step (thinking/tool_use/text) in order,
plus tool_results, grouped per user turn. Preserves the agentic rhythm so CoT can be
synthesized BEFORE every tool_use and the final text."""
import json, glob, os

PROJ = os.path.expanduser("~/.claude/projects")
OUT = "/home/lane/cc/data/fable5_seq.jsonl"

def clean_user(content):
    if isinstance(content, str):
        s = content.strip()
        if not s or s.startswith("<") or "command-name" in s or "local-command" in s:
            return None
        return s
    parts = []
    for b in content:
        if isinstance(b, dict) and b.get("type") == "tool_result":
            return None
        if isinstance(b, dict) and b.get("type") == "text":
            parts.append(b.get("text", ""))
    s = "\n".join(parts).strip()
    return s or None

def tool_result_text(content):
    if isinstance(content, list):
        out = []
        for b in content:
            if isinstance(b, dict) and b.get("type") == "tool_result":
                c = b.get("content")
                if isinstance(c, list):
                    out.append(" ".join(x.get("text","") for x in c if isinstance(x,dict)))
                elif isinstance(c, str):
                    out.append(c)
        return "\n".join(out).strip()
    return ""

turns = []
for fn in glob.glob(f"{PROJ}/*/*.jsonl"):
    raw = []
    for line in open(fn, errors="ignore"):
        try: o = json.loads(line)
        except: continue
        if o.get("type") in ("user", "assistant"):
            raw.append(o)

    cur = None  # current turn dict
    for o in raw:
        typ = o["type"]; m = o.get("message", {}); content = m.get("content")
        if typ == "user":
            u = clean_user(content)
            if u is not None:
                if cur and cur["steps"]:
                    turns.append(cur)
                cur = {"source": os.path.basename(fn), "user": u, "steps": []}
            else:
                # tool_result feeding the running turn
                if cur is not None:
                    tr = tool_result_text(content)
                    if tr:
                        cur["steps"].append({"kind": "tool_result", "text": tr[:1200]})
        elif typ == "assistant" and m.get("model") == "claude-fable-5" and cur is not None:
            if not isinstance(content, list):
                continue
            for b in content:
                if not isinstance(b, dict): continue
                t = b.get("type")
                if t == "tool_use":
                    cur["steps"].append({"kind": "tool_use",
                                          "name": b.get("name",""),
                                          "input": b.get("input", {})})
                elif t == "text":
                    txt = b.get("text","").strip()
                    if txt:
                        cur["steps"].append({"kind": "text", "text": txt})
                # thinking blocks are encrypted/empty -> ignored, we synthesize CoT
    if cur and cur["steps"]:
        turns.append(cur)

# keep turns that actually have at least one tool_use or final text
turns = [t for t in turns if any(s["kind"] in ("tool_use","text") for s in t["steps"])]

with open(OUT, "w") as f:
    for t in turns:
        f.write(json.dumps(t) + "\n")

n_tool = sum(sum(1 for s in t["steps"] if s["kind"]=="tool_use") for t in turns)
n_text = sum(sum(1 for s in t["steps"] if s["kind"]=="text") for t in turns)
print(f"{len(turns)} turns | {n_tool} tool_use steps | {n_text} text steps -> {OUT}")
print(f"avg steps/turn: {sum(len(t['steps']) for t in turns)/max(len(turns),1):.1f}")

